import sys
input = sys.stdin.read

def max_erased_elements(n, a):
    max_erase = 0
    for i in range(n):
        for j in range(i, n):
            if (j - i + 1) > max_erase:
                if i == 0 or j == n-1 or a[j+1] - a[i-1] == j - i + 1 + 1:
                    max_erase = j - i + 1
    return max_erase

